try:
    from inspect import signature
except ImportError:
    from funcsigs import signature


class ArgumentReplacer(object):
    """
    This class provides a streamlined way of replacing the value of the
    specified argument as passed to the decorated subroutine.
    """
    def __init__(self, subroutine, arg_name):
        self.signature = signature(subroutine)
        self.subroutine = subroutine
        self.arg_name = arg_name

        self._check_argument_in_signature()

    def _check_argument_in_signature(self):
        if self.arg_name not in self.signature.parameters:
            exc_msg = "no {!r} argument found in {!r} signature."
            exc_msg = exc_msg.format(self.arg_name, self.subroutine.__name__)
            raise TypeError(exc_msg)

    def replace_and_call(self, args, kwargs):
        """Create a new parameter replacement context.

        args, kwargs - the arguments that will be passed to the subroutine
            specified in __init__.

        Use this as a context manager.
        Returns an instance of ArgumentReplacer, which will call the subroutine
        given to this object's __init__ method, upon exiting from the context.
        """
        bound_args = self.signature.bind(*args, **kwargs)
        self._apply_default(bound_args)
        return ReplaceableValue(self.subroutine, bound_args, self.arg_name)

    # We don't need to apply every default - just the one that's used as the
    # argument that's being replaced.
    def _apply_default(self, bound_arguments):
        if self.arg_name not in bound_arguments.arguments:
            default = self.signature.parameters[self.arg_name].default
            bound_arguments.arguments[self.arg_name] = default


class ReplaceableValue(object):
    """Object representation of "get argument, replace it, call" context.

    Use ArgumentReplacer.replace_and_call to create it.
    After exiting from context, calls the subroutine with the value of
    specified parameter changed according to it's attributes.

    Attributes:
        subroutine - function or method to be called
        bound_args - return value of inspect.Signature.bind
        arg_name - name of the argument that the value attribute references
        value - value of the argument to be changed
        returned_value (available after __exit__) - value returned by the
        subroutine.
    """

    def __init__(self, subroutine, bound_args, arg_name):
        self.bound_args = bound_args
        self.arg_name = arg_name
        self.subroutine = subroutine

    def __enter__(self):
        return self

    def __exit__(self, _, exception, __):
        if exception is not None:
            return
        args = self.bound_args.args
        kwargs = self.bound_args.kwargs
        self.returned_value = self.subroutine(*args, **kwargs)

    @property
    def value(self):
        return self.bound_args.arguments[self.arg_name]

    @value.setter
    def value(self, value):
        name = self.arg_name
        self.bound_args.arguments[name] = value
